    a = list(map(int, lines[1].split()))

    # Count frequency of each value
    from collections import Counter
    cnt = Counter(a)

    # If any value appears 3+ times, impossible
    for count in cnt.values():
        if count > 2:
            return "NO"

    res = []
    last_incr = float('-inf')
    last_decr = float('inf')

    for i in range(n):
        x = a[i]
        assigned = False

        # Try decreasing sequence first (more constrained for ordering)
        if x < last_decr:
            last_decr = x
            res.append(1)
            assigned = True

        # If can't go to decreasing, try increasing
        if not assigned and x > last_incr:
            last_incr = x
            res.append(0)
            assigned = True

        # If neither works, impossible
        if not assigned:
            # Special check: if x equals last_incr and count of x is 2,
            # we must use decreasing; if equals last_decr and count is 2, must use increasing
