                    last_decr = x
                    res.append(1)
                    assigned = True
                else:
                    # Can't go to decreasing either
                    return "NO"
            elif x == last_decr:
                # Must use increasing
                if x > last_incr:
                    last_incr = x
                    res.append(0)
                    assigned = True
                else:
                    return "NO"
            else:
                return "NO"

    return "YES\n" + " ".join(map(str, res)) + "\n"

