def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "-1"
    n, m, k = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    # DFS to find cycles via back edges
    visited = [False] * (n + 1)
    parent = [0] * (n + 1)
    cycles = []

    def dfs_cycle(u, p, path):
        visited[u] = True
        for v in adj[u]:
            if v == p:
                continue
            if visited[v]:
                # Back edge creates a cycle
                cycle = []
                curr = u
                while curr != v:
                    cycle.append(curr)
                    curr = parent[curr]
                cycle.append(v)
                cycle.append(u)
                cycles.append(cycle)
            else:
                parent[v] = u
                dfs_cycle(v, u, path + [v])

    dfs_cycle(1, 0, [1])

    # Check if we can find k cycles with representatives
    cycles_with_reps = []
    used = [False] * (n + 1)

    for cycle in cycles:
        rep_found = False
        for v in cycle:
            if not used[v]:
                used[v] = True
                rep_found = True
                break
        if rep_found:
            cycles_with_reps.append(cycle)

    if len(cycles_with_reps) >= k and n >= k:
        output = ["CYCLES"]
        for i in range(k):
            cyc = cycles_with_reps[i]
            output.append(str(len(cyc)))
            # Output starting from representative
            if len(cyc) > 1:
                jump = [(cyc[j] - i) % len(cyc)] * (len(cyc) - 1)
                if jump[0] == len(cyc):
                    jump = [(cyc[(j - i - 1) % len(cyc)] for j in range(1, len(cyc)))
                    output.append(" ".join(cyc))
                else:
                    output.append(" ".join(str(cyc[(j - i) % len(cyc)]) for j in range(len(cyc))))
            else:
                output.append(" ".join(str(cyc[j]) for j in range(len(cyc))))
        return "\n".join(output)

    # Try to find a long path
    if n / k <= n:
        # We need path length >= ceil(n/k)
        needed = (n + k - 1) // k

        visited = [False] * (n + 1)
        max_len = 0
        best_path = []

        def find_long_path(start):
            nonlocal max_len, best_path
            path = [start]
            visited[start] = True
            stack = [(start, 0, path)]
            visited[start] = False

            while stack:
                u, dist, p = stack.pop()
                if dist > max_len:
                    max_len = dist
                    best_path = p.copy()
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append((v, dist + 1, p.copy() + [v]))
                        visited[v] = False

        for i in range(1, n + 1):
            find_long_path(i)

        if max_len >= needed:
            output = ["PATH", str(max_len + 1)]  # max_len is number of edges
            output.append(" ".join(str(v) for v in best_path))
            return "\n".join(output)

    return "-1"

def solution(input_data):
    # Parse the input
    lines = input_data.strip().split('\n')
    if not lines:
        return ""

    first_line = lines[0].strip()
    if not first_line:
        return ""

    n, m = map(int, first_line.split())

    # Get the grid rows
    grid = []
    for i in range(n):
        if i + 1 < len(lines):
            grid.append(list(lines[i + 1]))
        else:
            grid.append(['.' * m])

    # Extend grid if n > actually provided lines
    # (for safety, though input should be valid)
    if len(grid) < n:
        while len(grid) < n:
            grid.append(['.' * m])

    # Process the grid
    visited = [[False] * m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and not visited[i][j]:
                # Found a new connected component
                points = []
                stack = [(i, j)]
                visited[i][j] = True

                while stack:
                    r, c = stack.pop()
                    points.append((r, c))

                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            if grid[nr][nc] == '.' and not visited[nr][nc]:
                                visited[nr][nc] = True
                                stack.append((nr, nc))

                # Calculate bounding box of this component
                if points:
                    min_r = min(p[0] for p in points)
                    max_r = max(p[0] for p in points)
                    min_c = min(p[1] for p in points)
                    max_c = max(p[1] for p in points)

                    # Within the bounding box, remove all '*' walls
                    for r in range(min_r, max_r + 1):
                        for c in range(min_c, max_c + 1):
                            if grid[r][c] == '*':
                                grid[r][c] = '.'

    # Convert grid to string and return
    return '\n'.join(''.join(row) for row in grid)

