def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    clauses = []
    var_to_clauses = defaultdict(list)  # var -> list of (clause_idx, literal_value)
    var_clause_count = [0] * (m + 1)

    for i in range(n):
        parts = list(map(int, lines[i + 1].split()))
        k = parts[0]
        literals = parts[1:]
        clauses.append(literals)
        for lit in literals:
            var = abs(lit)
            var_to_clauses[var].append((i, lit))
            var_clause_count[var] += 1

    assignment = [0] * m  # 0 = unassigned, 1 = true, -1 = false

    # Build clause-satisfaction tracking
    def check_clause(clause, assign):
        for lit in clause:
            var_idx = abs(lit) - 1
            val = assign[var_idx]
            if val == 0:
                continue  # not assigned yet
            lit_val = 1 if lit > 0 else -1
            if val * lit_val > 0:  # var matches literal (or negated var matches negated literal)
                return True
        return False

    # Count how many clauses are satisfied
    def count_satisfied(assign):
        count = 0
        for i in range(n):
            clause = clauses[i]
            is_sat = False
            for lit in clause:
                var_idx = abs(lit) - 1
                val = assign[var_idx]
                if val != 0:
                    lit_val = 1 if lit > 0 else -1
                    if val * lit_val > 0:
                        is_sat = True
                        break
            if is_sat:
                count += 1
        return count

    def all_satisfied(assign):
        cnt = count_satisfied(assign)
        return cnt == n

    def get_remaining_variables():
        return [i for i in range(m) if assignment[i] == 0]

    def solve():
        if all_satisfied(assignment):
            return True

        remaining = get_remaining_variables()
        if not remaining:
            return all_satisfied(assignment)

        # Pick a variable that has the most impact (iterate through remaining ones)
        # Try to assign this variable to either true or false
        for var_idx in remaining:
            # Try both values
            for val in [1, -1]:
                assignment[var_idx] = val
                if solve():
                    return True
                assignment[var_idx] = 0

        return False

    if solve():
        result = [str(assignment[i]) for i in range(m)]
        return "YES\n" + "".join(result)
    else:
        return "NO"


