from collections import deque

def bfs(start, end, excluded_edges, n, adj):
    """Check if there's a path from start to end, avoiding edges in excluded_edges"""
    visited = [False] * (n + 1)
    queue = deque([start])
    visited[start] = True

    while queue:
        curr = queue.popleft()
        if curr == end:
            return True
        for neighbor, weight, edge_id in adj[curr]:
            if edge_id not in excluded_edges and not visited[neighbor]:
                visited[neighbor] = True
                queue.append(neighbor)
    return False

