def is_gp(arr):
    n = len(arr)
    if n <= 1:
        return True

    # If first element is 0, all elements must be 0
    if arr[0] == 0:
        return all(x == 0 for x in arr)

    # Check geometric progression using cross-multiplication to avoid division
    # A GP requires: arr[i] / arr[i-1] = arr[1] / arr[0] for all i
    # Cross-multiplying: arr[i] * arr[0] == arr[i-1] * arr[1]
    r_num, r_den = arr[1], arr[0]

    for i in range(2, n):
        if arr[i] * r_den != arr[i-1] * r_num:
            return False

    return True

