def combinations_nk(n, k):
    """Compute nCk using Decimal for precision"""
    if k < 0 or k > n:
        return Decimal(0)
    if k == 0 or k == n:
        return Decimal(1)
    if k > n // 2:
        k = n - k

    num = Decimal(1)
