def solution(s):
    n = len(s)
    if n == 0:
        return "1\n1 0"

    max_len = 0
    best_middle = None

    # Find the longest palindrome substring
    for length in range(1, n + 1, 2):  # Only odd lengths
        for start in range(n - length + 1):
            sub = s[start:start + length]
            if sub == sub[::-1]:
                max_len = length
                best_middle = start

    if best_middle is not None:
        prefix_len = min(best_middle, n - (best_middle + max_len))

        for x in range(prefix_len, 0, -1):  # Try longest prefix/suffix first
            for i in range(best_middle - x + 1):
                for j in range(best_middle + max_len, n - x + 1):
                    if s[i:i+x] == s[j:j+x]:
                        return f"1\n{start + 1} {length}"
                    break
            break

    return f"1\n1 {n}"

