    ops_to_zero = []
    for val in a:
        if val == 0:
            ops = 0
        else:
            ops = abs(val) // x
            if abs(val) % x != 0:
                ops += 1
        ops_to_zero.append(ops)

    # Sort indices by operations needed to zero (greedy approach)
    indices_by_cost = sorted(range(n), key=lambda i: ops_to_zero[i])

    # Greedily zero out elements
    for i in indices_by_cost:
        if ops_remaining >= ops_to_zero[i]:
            b[i] = 0
            ops_remaining -= ops_to_zero[i]
        else:
            break

    # Check if product is still positive
    temp_prod = 1
    pos_count = 0
    for val in b:
        temp_prod *= val
        if val > 0:
            pos_count += 1

    # If product is positive and we can improve it, work on topology
    if ops_remaining > 0 and pos_count == n and not (0 in b):
        # All values are positive, need to make product negative or zero
        # Calculate cost to make each element negative
        can_make_neg = []
        for i, val in enumerate(b):
            ops = ops_to_zero[i]  # ops to make 0
            can_make_neg.append((i, ops))

        # If we can make any element 0 with remaining ops, do it
        for idx, ops in can_make_neg:
            if ops_remaining >= ops:
                b[idx] = 0
                ops_remaining -= ops
                break

        # After trying to zero, check again if we can flip signs
        if ops_remaining > 0:
            for i in range(n):
                if ops_remaining >= ops_to_zero[i]:
                    b[i] = 0
                    ops_remaining -= ops_to_zero[i]
                elif a[i] != 0:
