def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def all_coprime(seq):
    for i in range(len(seq)):
        for j in range(i + 1, len(seq)):
            if gcd(seq[i], seq[j]) != 1:
                return False
    return True

