def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    if n < 2:
        return "-1"

    # Parse cost matrix
    # For each row i, we have N-1 integers (skipping A[i][i])
    cost = [[0] * n for _ in range(n)]
    for i in range(n):
        parts = list(map(int, lines[i+1].split()))
        idx = 0
        for j in range(n):
            if j == i:
                continue
            cost[i][j] = parts[idx]
            idx += 1

    # Build preference rankings (lower cost = better preference)
    pref = [[0] * n for _ in range(n)]
    for i in range(n):
        pairs = sorted([(cost[i][j], j) for j in range(n) if j != i])
        for rank, (_, j) in enumerate(pairs):
            pref[i][j] = rank

    # matching[i] stores the partner of city i, -1 if unmatched
    matching = [-1] * n
    matched = [False] * n

    # Greedy initialization: build initial matching
    for _ in range(n):
        for i in range(n):
            if matched[i]:
                continue

            best_j = -1
            best_rank = n + 1
            for j in range(n):
                if j == i:
                    continue
                if matching[j] == -1:  # j is unmatched
                    if pref[i][j] < best_rank:
                        best_rank = pref[i][j]
                        best_j = j

            if best_j == -1:
                return "-1"

            matching[i] = best_j
            matching[best_j] = i
            matched[i] = matched[best_j] = True

    # Greedy matching only works for some cases.
    # For the stable roommates problem, we need to check for blocking pairs.
    # A blocking pair is (i, j) where both prefer each other to current matches

    # Try to improve matching by resolving blocking pairs
    for _ in range(n * 2):  # Limit iterations
        changed = False
        blocking_found = False

        for i in range(n):
            if matching[i] == -1:
                continue

            current = matching[i]  # i's current partner
            for j in range(n):
                if j == i or matching[j] == -1:
                    continue

                # Skip if j is already i's partner
                if matching[j] == i:
                    continue

                # Check if i prefers j over current partner
                if pref[i][j] < pref[i][current]:
                    # Check if j also prefers i over current partner
                    j_current = matching[j]
                    if pref[j][i] < pref[j][j_current]:
                        # Found blocking pair (i, j)
                        blocking_found = True

                        # Attempt to reassign: i takes j, j finds new partner
                        matching[i] = j
                        matching[j] = -1  # j temporarily unmatched

                        if matching[current] == -1:
                            matching[current] = j
                        elif matching[matching[current]] == current:
                            matching[matching[current]] = -1

                        changed = True
                        break

            if blocking_found:
                break

        if not blocking_found:
            break

    # Final stability check
    stable = True
    for i in range(n):
        if matching[i] == -1:
            stable = False
            break

        for j in range(n):
            if j == i or matching[j] == -1:
                continue

            if matching[j] != i:
                i_prefers_j = pref[i][j] < pref[i][matching[i]]
                j_prefers_i = pref[j][i] < pref[j][matching[j]]

                if i_prefers_j and j_prefers_i:
                    stable = False
                    break
        if not stable:
            break

    if not stable:
        return "-1"

    # Output: for each city i, its partner (1-indexed)
    return '\n'.join(str(matching[i] + 1) for i in range(n))


