        max_next = current + m
        for next_planet in range(1, max_next + 1):
            if next_planet <= n and not used[next_planet]:
                used[next_planet] = True
                count = (count + count_sequences(next_planet, remaining - 1, used)) % MOD
                used[next_planet] = False
        return count

    total = 0
    for start in range(1, n + 1):
        used = [False] * (n + 1)
        used[start] = True
        total = (total + count_sequences(start, k - 1, used)) % MOD

    return str(total)

