    min_wait = float('inf')
    best_time = ts

    def check_candidate(arr):
        if arr < ts:
            return float('inf'), None

        # Calculate when all visitors arriving before arr get served
        current_time = arr
        for v in visitors:
            if v < arr:
                current_time = max(current_time, v) + t
            else:
                break

        if current_time > tf:
            return float('inf'), None

        # Find max arrival among visitors before Vasya (strictly before arr)
        max_arrival_before = 0
        for v in visitors:
            if v < arr:
                max_arrival_before = v
                break

        queue_time = max(0, max_arrival_before)
        return queue_time, arr

    candidates = []
    candidates.append(ts)
    for v in visitors:
        candidates.append(v)
        if v > ts:
            candidates.append(v - 1)

    for arr in candidates:
        if arr < ts:
            continue

        if arr < tf:
            queue_time, valid_time = check_candidate(arr)
            if queue_time < min_wait:
                min_wait = queue_time
                best_time = arr
            elif queue_time == min_wait:
                best_time = arr

