def solution(input_string):
    lines = input_string.strip().split('\n')
    if not lines:
        return "0\n"

    first_line = lines[0].split()
    N = int(first_line[0])
    M = int(first_line[1])
    K = int(first_line[2])

    # Map position -> total energy at that position
    energy_at_position = {}

    for i in range(1, K + 1):
        parts = lines[i].split()
        if len(parts) < 5:
            continue
        x, y, d, t = int(parts[0]), int(parts[1]), int(parts[2]), int(parts[3])
        e = int(parts[4])

        # Check each of the 4 positions in the jumping pattern
        for pos_idx in range(4):
            # Calculate position for this phase
            if pos_idx == 0:
                pos_i, pos_j = x, y
            elif pos_idx == 1:
                pos_i, pos_j = x + d, y - d
            elif pos_idx == 2:
                pos_i, pos_j = x + d, y
            else:
                pos_i, pos_j = x, y + d

            # Time when we visit this position = pos_i + pos_j
            # For a transformer meeting us here: (arrival_time - t) mod 4 == pos_idx
            meeting_time = pos_i + pos_j

            if 0 <= pos_i < N and 0 <= pos_j < M:
                if (meeting_time - t) % 4 == pos_idx:
                    energy_at_position[(pos_i, pos_j)] = energy_at_position.get((pos_i, pos_j), 0) + e

    # DP to find minimum energy to reach (N-1, M-1)
    # dp[i][j] = minimum energy cost to reach position (i,j)
    INF = float('inf')
    dp = [[INF] * M for _ in range(N)]

    # Starting position
    dp[0][0] = energy_at_position.get((0, 0), 0)

    for i in range(N):
        for j in range(M):
            # Skip starting position (already set)
            if i == 0 and j == 0:
                continue

            # Get minimum from top or left
            if i > 0:
                dp[i][j] = min(dp[i][j], dp[i-1][j])
            if j > 0:
                dp[i][j] = min(dp[i][j], dp[i][j-1])

            # Add energy cost at this position
            if (i, j) in energy_at_position:
                dp[i][j] += energy_at_position[(i, j)]

    return str(dp[N-1][M-1]) + '\n'


