def count_components(adj):
    """Count connected components in the character graph"""
    visited = set()
    components = set()

    def dfs(char):
        stack = [char]
        while stack:
            curr = stack.pop()
            if curr in visited:
                continue
            visited.add(curr)
            for nxt in adj.get(curr, []):
                if nxt not in visited:
                    stack.append(nxt)
        components.add(curr)

    for char in "abcdefghijklmnopqrst":
        if char not in visited:
            dfs(char)

    return len(components)

