def solution(input_str):
    input_lines = input_str.strip().split('\n')
    n, a, b = map(int, input_lines[0].split())
    p = list(map(int, input_lines[1].split()))

    # Map each value to its index
    pos = {val: i for i, val in enumerate(p)}

    # Build graph for connected components - connect numbers that must be together
    # If x is in A, a-x must be in A (they're tied together)
    # If x is in B, b-x must be in B (they're tied together)
    graph = {}
    for i in range(n):
        graph[i] = []

        val = p[i]
        # Check if a-val exists in array
        if (a - val) in pos:
            j = pos[a - val]
            graph[i].append(j)
            graph[j].append(i)

        # Check if b-val exists in array
        if (b - val) in pos:
            j = pos[b - val]
            graph[i].append(j)
            graph[j].append(i)

    # Find connected components
    visited = [False] * n
    components = []

    for i in range(n):
        if not visited[i]:
            comp = []
            stack = [i]
            visited[i] = True
            while stack:
                idx = stack.pop()
                comp.append(idx)
                for v in graph[idx]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
            components.append(comp)

    # Result array (0 for set A, 1 for set B)
    result = [0] * n

    for comp in components:
        # Check if all numbers in component can go to set A
        can_be_in_A = True
        for idx in comp:
            val = p[idx]
            if (a - val) not in pos:
                can_be_in_A = False
                break

        # Check if all numbers in component can go to set B
        can_be_in_B = True
        for idx in comp:
            val = p[idx]
            if (b - val) not in pos:
                can_be_in_B = False
                break

        # If neither works, impossible
        if not can_be_in_A and not can_be_in_B:
            return "NO"

        # If both work, prefer A (arbitrary choice, both valid)
        if can_be_in_A:
            for idx in comp:
                result[idx] = 0
        else:
            for idx in comp:
                result[idx] = 1

    # Verify assignment is correct
    for i in range(n):
        if result[i] == 0:  # In set A
            if (a - p[i]) in pos:
                j = pos[a - p[i]]
                if result[j] != 0:
                    return "NO"
        else:  # In set B
            if (b - p[i]) in pos:
                j = pos[b - p[i]]
                if result[j] != 1:
                    return "NO"

    # Success - format output
    output_nums = " ".join(str(result[i]) for i in range(n))
    return f"YES\n{output_nums} \n"


