def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines or not lines[0]:
        return "0.000000000000"

    parts = lines[0].split()
    if not parts:
        return "0.000000000000"
    n, m = int(parts[0]), int(parts[1])

    if n == 0:
        return "0.000000000000"

    prob_list = []
    for i in range(n):
        if 1 + i < len(lines) and lines[1 + i]:
            row = list(map(int, lines[1 + i].split()))
            if len(row) == m:
                prob_list.append([float(x) / 1000.0 for x in row])

    if not prob_list:
        return "0.000000000000"

    # Collect all marginal gains from all sizes
    all_marginals = []

    for s in range(m):
        # dp[t] = probability exactly t engineers need size s among processed so far
        dp = [0.0] * (n + 1)
        dp[0] = 1.0

        for i in range(n):
            if i < len(prob_list):
                p = prob_list[i][s]
                new_dp = [0.0] * (n + 1)
                for t in range(i + 2):
                    new_dp[t] = dp[t] * (1 - p)
                    if t >= 1:
                        new_dp[t] += dp[t - 1] * p
                dp = new_dp

        # Compute g[k] = P(at least k engineers need size s) for k=1 to n
        for k in range(1, n + 1):
            g = sum(dp[t] for t in range(k, n + 1))
            all_marginals.append(g)

    # Sort in descending order, top n
    all_marginals.sort(reverse=True)

    # Sum the top n marginal gains (or all available if less than n)
    result = sum(all_marginals[:n])

    return f"{result:.12f}"

def solution(input_data):
