    responses = []
    while idx < len(lines):
        line = lines[idx].strip().lower()
        if line in ('yes', 'no'):
            responses.append(line)
            idx += 1
        else:
            break

    a = [0] * (n + 1)
    for i in range(1, n + 1):
        for bit in range(b):
            resp_idx = (i - 1) * b + bit
            if resp_idx < len(responses):
                if responses[resp_idx] == 'yes':
                    a[i] |= (1 << bit)

    max_val = max(a[1:]) if any(v for v in a[1:]) else 0
    binary = bin(max_val)[2:].zfill(b)
    return f'\n0 {binary}\n'

